export const metadata = { title: "Overview" };

export default async function AdminOverviewPage() {
const { users, spaces, outbox, redisConfigured, filesConfigured } = await invokeBackend<Views["admin-page:loadAdminOverviewPage"]>("view", "admin-page:loadAdminOverviewPage", []);

return (
    <div className="flex flex-col gap-6">
      <PageHeader title="Instance admin" description="Operations for this Space Works instance. Space content stays private to members." />
      <section className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatTile label="Users" value={users} href="/admin/users" />
        <StatTile label="Spaces" value={spaces} href="/admin/spaces" />
        <StatTile label="Emails waiting" value={outbox.counts.PENDING} href="/admin/outbox" />
        <StatTile label="Emails failed" value={outbox.counts.FAILED} tone={outbox.counts.FAILED > 0 ? "attention" : "default"} href="/admin/outbox" />
      </section>
      <Card>
        <CardHeader title="Services" />
        <ul className="flex flex-col gap-2 text-body-ui text-ink">
          <li>Redis: {redisConfigured ? "configured" : "not configured (rate limits and realtime use this process only)"}</li>
          <li>Object storage: {filesConfigured ? "configured" : "not configured (development disk fallback)"}</li>
          <li>
            Email and account sign-up: <Link href="/admin/settings" className="font-semibold underline underline-offset-4">instance settings</Link>
          </li>
        </ul>
      </Card>
    </div>
  );
}

