export const metadata = { title: "Spaces" };

export default async function AdminSpacesPage() {
const { spaces, tz } = await invokeBackend<Views["admin-spaces-page:loadAdminSpacesPage"]>("view", "admin-spaces-page:loadAdminSpacesPage", []);

return (
    <div className="flex flex-col gap-6">
      <PageHeader title="Spaces" description="Each space is one makerspace with its own stock, members and settings. Names and member counts only; space content stays private to members." />
      <CreateSpaceForm />
